// AvgustovStory 1.1 (generated by quest_generator/gen/story_extras.js, do not edit by hand)
// The server plays in guilds (FTB Teams parties, up to 4 players). When a guild opens one of Master August's letters,
// its online members see the chapter title card, and the whole server reads in chat which guild got there (and whether it was first).
const AV_STORY_TITLES = {
  "577642ADDF95E032": [
    "Пролог",
    "Новая земля"
  ],
  "66ED7F7448F796FE": [
    "Глава I",
    "Первая шестерня"
  ],
  "21255BCC44ED797D": [
    "Глава II",
    "Огонь из-под земли"
  ],
  "78B5B9A254BDDA39": [
    "Глава III",
    "За горизонт"
  ],
  "465941E135A689AB": [
    "Глава IV",
    "Небо артели"
  ],
  "37C7E988DD06B6B3": [
    "Глава V",
    "Город машин"
  ],
  "7C9CA89A3742B492": [
    "Глава VI",
    "Железная дорога"
  ],
  "5927541A6852BA3D": [
    "Глава VII",
    "Сталь"
  ],
  "066C0076956AAE88": [
    "Глава VIII",
    "Стражи Предтеч"
  ],
  "141E0EDDF78B547B": [
    "Глава IX",
    "К звёздам"
  ],
  "460A44F163F7847C": [
    "Эпилог",
    "История артели"
  ]
};
Object.keys(AV_STORY_TITLES).forEach(function (id) {
  FTBQuestsEvents.completed(id, function (e) {
    var t = AV_STORY_TITLES[id];
    var s = e.server;
    var guild = '';
    try { guild = String(e.data.data.name); } catch (x) {}
    var key = 'av_letter_first_' + id;
    var first = !s.persistentData.getBoolean(key);
    if (first) s.persistentData.putBoolean(key, true);
    e.onlineMembers.forEach(function (p) {
      var n = p.username;
      s.runCommandSilent('title ' + n + ' times 10 80 30');
      s.runCommandSilent('title ' + n + ' subtitle ' + JSON.stringify({ text: t[1], color: 'gray', italic: true }));
      s.runCommandSilent('title ' + n + ' title ' + JSON.stringify({ text: t[0], color: 'gold', bold: true }));
      s.runCommandSilent('execute as ' + n + ' at @s run playsound minecraft:ui.toast.challenge_complete master @s ~ ~ ~ 0.7 0.8');
    });
    s.runCommandSilent('tellraw @a ' + JSON.stringify([
      { text: (guild ? 'Гильдия «' + guild + '»' : 'Гильдия') + (first ? ' первой' : '') + ' открыла главу: ', color: 'gold' },
      { text: t[0] + (t[1] ? '. ' + t[1] : ''), color: 'yellow' },
      { text: ' — письмо мастера Августа ждёт в книге квестов.', color: 'gray' }]));
  });
});

// Chronicle pages: a map waypoint for the whole guild where the page was found.
const AV_PAGE_WAYPOINTS = {
  "4C9138ED290F5D61": "Страница 1: Мы пришли первыми",
  "136D243046ECF770": "Страница 2: Ветер и вода",
  "1208C18957072236": "Страница 3: Укрощение огня",
  "6D0EBADDF753515D": "Страница 4: Город под волнами",
  "6C2B55B818AC4F67": "Страница 5: Украденное небо",
  "5080490B94FDC787": "Страница 6: Литейная",
  "07049344D99E519F": "Страница 7: Последний поезд",
  "4CE27C1BF38E94F4": "Страница 8: Ракетная фабрика",
  "672FF7EFC7AFD2A5": "Страница 9: Ядро стража",
  "16BD5124B9B1A7B0": "Страница 10: Клятва огня"
};
Object.keys(AV_PAGE_WAYPOINTS).forEach(function (id) {
  FTBQuestsEvents.completed(id, function (e) {
    var members = e.onlineMembers;
    if (members.isEmpty()) return;
    var finder = e.player || members.iterator().next();
    var pos = finder.blockPosition();
    var dim = String(finder.level.dimension);
    var name = JSON.stringify(AV_PAGE_WAYPOINTS[id]);
    members.forEach(function (p) {
      e.server.runCommandSilent('execute as ' + p.username + ' run ftbchunks waypoint add ' + name + ' ' + pos.x + ' ' + pos.y + ' ' + pos.z + ' ' + dim);
      e.server.runCommandSilent('tellraw ' + p.username + ' ' + JSON.stringify({ text: 'На карте отмечено место: ' + AV_PAGE_WAYPOINTS[id], color: 'aqua' }));
    });
  });
});
